      // Ticket details
      subject: text("subject").notNull(),
      description: text("description").notNull(),
      // Status and priority
      status: text("status").notNull().default("open"),
      // 'open' | 'in_progress' | 'waiting_customer' | 'resolved' | 'closed'
      priority: text("priority").notNull().default("medium"),
      // 'low' | 'medium' | 'high' | 'urgent'
      category: text("category").notNull().default("general"),
      // 'technical' | 'billing' | 'feature_request' | 'bug_report' | 'complaint' | 'general'
      // AI-powered features
      aiPriority: text("ai_priority"),
      // AI-suggested priority
      aiCategory: text("ai_category"),
      // AI-suggested category
      sentimentScore: numeric("sentiment_score", { precision: 3, scale: 2 }),
      // -1.00 to 1.00 (negative to positive)
      emotionalState: text("emotional_state"),
      // 'happy' | 'neutral' | 'frustrated' | 'angry'
      churnRisk: text("churn_risk").notNull().default("low"),
      // 'low' | 'medium' | 'high' | 'critical'
      aiAnalysis: text("ai_analysis"),
      // JSON with AI insights, keywords, suggested actions
      aiDraftedResponse: text("ai_drafted_response"),
      // AI-generated suggested response
      // Auto-resolution tracking
      autoResolved: text("auto_resolved").notNull().default("false"),
      // 'true' | 'false' - Whether AI resolved without human intervention
      autoResolvedAt: timestamp("auto_resolved_at"),
      autoResolutionSummary: text("auto_resolution_summary"),
      // Summary of how AI resolved the issue
