import { eq as eq20, and as and16, desc as desc4, sql as sql18 } from "drizzle-orm";
async function getMessagesFromPlatform(businessAccountId, platform, platformUserId, limit = 20) {
  switch (platform) {
    case "whatsapp":
      return getWhatsAppMessages(businessAccountId, platformUserId, limit);
    case "instagram":
      return getInstagramMessages(businessAccountId, platformUserId, limit);
    case "facebook":
      return getFacebookMessages(businessAccountId, platformUserId, limit);
    case "website":
      return getWebsiteMessages(businessAccountId, platformUserId, limit);
    default:
      return [];
  }
}
async function getWhatsAppMessages(businessAccountId, senderPhone, limit) {
  const rows = await db.select({
    rawMessage: whatsappLeads.rawMessage,
    direction: whatsappLeads.direction,
    receivedAt: whatsappLeads.receivedAt
  }).from(whatsappLeads).where(
    and16(
      eq20(whatsappLeads.businessAccountId, businessAccountId),
      eq20(whatsappLeads.senderPhone, senderPhone)
    )
  ).orderBy(desc4(whatsappLeads.receivedAt)).limit(limit);
  return rows.filter((r) => r.rawMessage).reverse().map((r) => ({
    platform: "whatsapp",
    role: r.direction === "incoming" ? "user" : "assistant",
    content: r.rawMessage,
    timestamp: r.receivedAt
  }));
}
async function getInstagramMessages(businessAccountId, senderId, limit) {
  const rows = await db.select({
    messageText: instagramMessages.messageText,
    direction: instagramMessages.direction,
    createdAt: instagramMessages.createdAt
  }).from(instagramMessages).where(
    and16(
      eq20(instagramMessages.businessAccountId, businessAccountId),
      eq20(instagramMessages.senderId, senderId)
    )
  ).orderBy(desc4(instagramMessages.createdAt)).limit(limit);
  return rows.filter((r) => r.messageText).reverse().map((r) => ({
    platform: "instagram",
    role: r.direction === "incoming" ? "user" : "assistant",
    content: r.messageText,
    timestamp: r.createdAt
  }));
}
async function getFacebookMessages(businessAccountId, senderId, limit) {
  const rows = await db.select({
    messageText: facebookMessages.messageText,
    direction: facebookMessages.direction,
    createdAt: facebookMessages.createdAt
  }).from(facebookMessages).where(
    and16(
      eq20(facebookMessages.businessAccountId, businessAccountId),
      eq20(facebookMessages.senderId, senderId)
    )
  ).orderBy(desc4(facebookMessages.createdAt)).limit(limit);
  return rows.filter((r) => r.messageText).reverse().map((r) => ({
    platform: "facebook",
    role: r.direction === "incoming" ? "user" : "assistant",
    content: r.messageText,
    timestamp: r.createdAt
  }));
}
async function getWebsiteMessages(businessAccountId, platformUserId, limit) {
  let convRows = await db.select({ id: conversations.id }).from(conversations).where(
    and16(
      eq20(conversations.businessAccountId, businessAccountId),
      eq20(conversations.visitorToken, platformUserId)
    )
  );
  if (convRows.length === 0) {
    const directConv = await db.select({ id: conversations.id }).from(conversations).where(
      and16(
        eq20(conversations.id, platformUserId),
        eq20(conversations.businessAccountId, businessAccountId)
      )
    ).limit(1);
    if (directConv.length > 0) {
      convRows = directConv;
    }
  }
  if (convRows.length === 0) {
    const leadConvs = await db.select({ conversationId: leads.conversationId }).from(leads).where(
      and16(
        eq20(leads.businessAccountId, businessAccountId),
        eq20(leads.phone, platformUserId)
      )
    );
    const convIds2 = leadConvs.map((l) => l.conversationId).filter(Boolean);
    if (convIds2.length === 0) return [];
    const validConvs = await db.select({ id: conversations.id }).from(conversations).where(
      and16(
        eq20(conversations.businessAccountId, businessAccountId),
        sql18`${conversations.id} IN (${sql18.join(convIds2.map((id) => sql18`${id}`), sql18`, `)})`
      )
    );
    const validConvIds = validConvs.map((c) => c.id);
    if (validConvIds.length === 0) return [];
    const rows2 = await db.select({
      content: messages.content,
      role: messages.role,
      createdAt: messages.createdAt
    }).from(messages).where(sql18`${messages.conversationId} IN (${sql18.join(validConvIds.map((id) => sql18`${id}`), sql18`, `)})`).orderBy(desc4(messages.createdAt)).limit(limit);
    return rows2.reverse().map((r) => ({
      platform: "website",
      role: r.role === "user" ? "user" : "assistant",
      content: r.content,
      timestamp: r.createdAt
    }));
  }
  const convIds = convRows.map((c) => c.id);
  const rows = await db.select({
    content: messages.content,
    role: messages.role,
    createdAt: messages.createdAt
  }).from(messages).where(sql18`${messages.conversationId} IN (${sql18.join(convIds.map((id) => sql18`${id}`), sql18`, `)})`).orderBy(desc4(messages.createdAt)).limit(limit);
  return rows.reverse().map((r) => ({
    platform: "website",
    role: r.role === "user" ? "user" : "assistant",
    content: r.content,
    timestamp: r.createdAt
  }));
}
async function shouldRefreshSnapshot(profileId, platform) {
  const snapshots2 = await db.select().from(customerMemorySnapshots).where(
    and16(
      eq20(customerMemorySnapshots.profileId, profileId),
      eq20(customerMemorySnapshots.platform, platform)
    )
  ).limit(1);
  if (snapshots2.length === 0) return true;
  const snapshot = snapshots2[0];
  if (snapshot.turnsSinceRefresh >= 3) return true;
  if (snapshot.lastMessageAt) {
    const staleMs = Date.now() - snapshot.lastMessageAt.getTime();
    if (staleMs > 30 * 60 * 1e3) return true;
  }
  return false;
}
