          [arabicUrduCount, "hi", "Hindi"],
          [tamilCount, "ta", "Tamil"],
          [teluguCount, "te", "Telugu"],
          [kannadaCount, "kn", "Kannada"],
          [malayalamCount, "ml", "Malayalam"],
          [bengaliCount, "bn", "Bengali"],
          [gujaratiCount, "gu", "Gujarati"],
          [gurmukhiCount, "pa", "Punjabi"],
          [odiaCount, "or", "Odia"]
