router2.get("/api/k12/search", requireAuth, async (req, res) => {
  const businessAccountId = getBusinessAccountId(req);
  if (!businessAccountId) return res.status(401).json({ error: "Unauthorized" });
  const query = (req.query.q || "").toLowerCase();
  if (!query) return res.json({ topics: [], questions: [] });
  const allTopics = await db.select().from(k12Topics).where(eq53(k12Topics.businessAccountId, businessAccountId));
  const matchedTopics = allTopics.filter(
    (t) => t.name.toLowerCase().includes(query) || t.description && t.description.toLowerCase().includes(query) || t.tags && t.tags.some((tag2) => tag2.toLowerCase().includes(query))
  );
  const topicIds = matchedTopics.map((t) => t.id);
  let matchedQuestions = [];
  if (topicIds.length > 0) {
    const allQuestions = await db.select().from(k12Questions).where(eq53(k12Questions.businessAccountId, businessAccountId));
    matchedQuestions = allQuestions.filter((q) => topicIds.includes(q.topicId));
  }
  res.json({ topics: matchedTopics, questions: matchedQuestions });
});
router2.get("/api/k12/external-api-config", requireAuth, requireBusinessAccount, requireRole("business_user", "super_admin"), requireTopScholarSuperAdminView, async (req, res) => {
  const businessAccountId = getBusinessAccountId(req);
  if (!businessAccountId) return res.status(401).json({ error: "Unauthorized" });
  const [account] = await db.select({
    topscholarApiBaseUrl: businessAccounts.topscholarApiBaseUrl,
    topscholarApiToken: businessAccounts.topscholarApiToken
  }).from(businessAccounts).where(eq53(businessAccounts.id, businessAccountId));
  if (!account) return res.status(404).json({ error: "Account not found" });
  res.json({
    apiBaseUrl: account.topscholarApiBaseUrl || "",
    apiToken: account.topscholarApiToken ? "\u2022\u2022\u2022\u2022\u2022\u2022\u2022\u2022" : "",
    configured: !!(account.topscholarApiBaseUrl && account.topscholarApiToken)
  });
});
router2.put("/api/k12/external-api-config", requireAuth, requireBusinessAccount, requireRole("business_user", "super_admin"), requireTopScholarSuperAdminView, async (req, res) => {
  const businessAccountId = getBusinessAccountId(req);
  if (!businessAccountId) return res.status(401).json({ error: "Unauthorized" });
  const { apiBaseUrl, apiToken } = req.body;
  const updates = {};
  if (apiBaseUrl !== void 0) {
    if (apiBaseUrl) {
      try {
        const url = new URL(apiBaseUrl);
        if (url.protocol !== "https:") {
          return res.status(400).json({ error: "API Base URL must use HTTPS" });
        }
        const hostname = url.hostname.toLowerCase();
        if (hostname === "localhost" || hostname === "127.0.0.1" || hostname === "0.0.0.0" || hostname.startsWith("10.") || hostname.startsWith("192.168.") || hostname.startsWith("172.") || hostname === "169.254.169.254" || hostname.endsWith(".internal") || hostname.endsWith(".local")) {
          return res.status(400).json({ error: "API Base URL cannot point to internal/private addresses" });
        }
      } catch {
        return res.status(400).json({ error: "Invalid API Base URL format" });
      }
    }
    updates.topscholarApiBaseUrl = apiBaseUrl || null;
  }
  if (apiToken !== void 0 && apiToken !== "\u2022\u2022\u2022\u2022\u2022\u2022\u2022\u2022") {
    updates.topscholarApiToken = apiToken || null;
  }
  if (Object.keys(updates).length === 0) {
    return res.status(400).json({ error: "No valid fields to update" });
  }
  await db.update(businessAccounts).set(updates).where(eq53(businessAccounts.id, businessAccountId));
  res.json({ success: true });
});
