    chapter: d.chapter ?? null,
    title: d.title ?? null,
    contentHtml: d.content_html ?? null,
    contentText: d.chunk_text ?? "",
    sourceRef: d.source_ref ?? null,
    mediaUrl: d.media_url ?? null,
