    const nextProvider = typeof req.body?.provider === "string" ? req.body.provider : current.provider;
    const nextAvatarId = req.body?.avatarId !== void 0 ? typeof req.body.avatarId === "string" ? req.body.avatarId.trim() : null : current.avatarId;
    let body = req.body;
    let avatarIdNotice = null;
